// Üretilen dosya: tool/ozgun/uret.py. Tarih · Millî Mücadele, Atatürk dönemi ve Cumhuriyet tarihi; 20. yüzyıl dünya tarihi (kolay).
const ozHistory4Kolay = <(String, String, List<String>, String)>[
  ('Osmanlı Devleti\'nin I. Dünya Savaşı\'ndan çekilmesini sağlayan ateşkes 30 Ekim 1918\'de hangi limanda, hangi gemide imzalanmıştır?', 'Limni Adası\'nın Mondros Limanı\'nda, Agamemnon zırhlısında', ['Selanik Limanı\'nda, İngiliz Kraliçe Elizabeth zırhlısında', 'Mudanya\'da, İron Duke savaş gemisinde', 'Brest-Litovsk\'ta, Hamidiye kruvazöründe'], 'Mondros Ateşkes Antlaşması, Osmanlı heyeti başkanı Rauf Bey ile İngiliz Amiral Calthorpe arasında Limni Adası\'ndaki Mondros Limanı\'nda, Agamemnon zırhlısında imzalanmıştır.'),
  ('Mondros Ateşkesi\'nin ardından İzmir\'i 15 Mayıs 1919\'da işgal eden devlet hangisidir?', 'Yunanistan', ['İtalya', 'Amerika Birleşik Devletleri', 'İngiltere'], 'Paris Barış Konferansı\'nın onayıyla Yunan kuvvetleri 15 Mayıs 1919\'da İzmir\'e çıkmıştır. Bu işgal, Kuvâ-yı Milliye ruhunun doğmasında önemli rol oynamıştır.'),
  ('İzmir\'in işgali sırasında işgalcilere ilk kurşunu sıkan ve bu yüzden şehit edilen gazeteci kimdir?', 'Hasan Tahsin', ['Yunus Nadi', 'Ahmet Ağaoğlu', 'Halide Edib'], 'Hüsrev Sami Bey olarak da bilinen gazeteci Hasan Tahsin, 15 Mayıs 1919\'da işgal birliklerine ilk kurşunu sıkmış ve orada şehit edilmiştir.'),
  ('Mondros sonrası kurulan aşağıdaki cemiyetlerden hangisi azınlıklar tarafından kurulmuş zararlı cemiyetlerdendir?', 'Mavri Mira', ['Redd-i İlhak', 'Müdafaa-i Hukuk', 'Teali-i İslam'], 'Mavri Mira, Rumların Bizans\'ı yeniden kurma hedefiyle İstanbul\'da Rum Patrikhanesi çevresinde örgütlediği bir cemiyettir. Teali-i İslam ise Türklerin kurduğu zararlı bir cemiyettir.'),
  ('İngiliz Muhipler Cemiyeti\'nin temel amacı aşağıdakilerden hangisidir?', 'İngiliz himayesi altında Osmanlı\'nın varlığını sürdürmek', ['Amerikan mandasını kabul ettirmek', 'Doğu Anadolu\'da bağımsız bir Kürt devleti kurmak', 'Saltanatı kaldırıp cumhuriyet ilan etmek'], 'Adından da anlaşılacağı gibi İngiliz Muhipler (İngiliz dostları) Cemiyeti, Osmanlı\'nın İngiltere\'nin koruması altında yaşamasını savunmuştur.'),
  ('Mustafa Kemal Samsun\'a hangi görevle gönderilmiştir?', '9. Ordu Müfettişi olarak', ['Kafkas Cephesi Komutanı olarak', 'Harbiye Nazırı olarak', 'Yıldırım Orduları Grubu Komutanı olarak'], 'Mustafa Kemal, bölgedeki asayişi sağlamak ve silahları toplatmak gerekçesiyle 9. Ordu (sonra 3. Ordu) Müfettişi sıfatıyla Bandırma Vapuru ile Samsun\'a gönderilmiştir.'),
  ('Amasya Genelgesi\'nde yer alan "Milletin istiklalini yine milletin azim ve kararı kurtaracaktır" ifadesi hangi düşünceyi açıkça ortaya koyar?', 'Millî egemenlik anlayışını', ['Laiklik ilkesini', 'Devletçilik politikasını', 'Halkçılığın sınıfsız toplum yorumunu'], 'Kurtuluşun padişahtan ya da yabancı yardımından değil milletin iradesinden geleceğini söyleyen bu ifade, millî egemenlik düşüncesinin ilk açık belirtilerinden biridir.'),
  ('Erzurum Kongresi\'nde alınan "Manda ve himaye kabul edilemez" kararının dayandığı temel ilke aşağıdakilerden hangisidir?', 'Tam bağımsızlık', ['Devletçilik', 'Laiklik', 'Ümmetçilik'], 'Manda ve himayenin reddi, bir başka devletin denetimini kabul etmemek anlamına gelir; bu, Millî Mücadele\'nin tam bağımsızlık hedefinin açık ifadesidir.'),
  ('Erzurum Kongresi\'nde seçilen Temsil Heyeti\'nin ilk başkanı kimdir?', 'Mustafa Kemal', ['Kâzım Karabekir', 'Rauf Orbay', 'Ali Fuat Cebesoy'], 'Kongreye başkanlık eden Mustafa Kemal, kongrede seçilen dokuz kişilik Heyet-i Temsiliye\'nin de başkanı olmuştur.'),
  ('Sivas Kongresi\'nde bütün cemiyetlerin "Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti" adı altında birleştirilmesi Millî Mücadele için ne sağlamıştır?', 'Ulusal güçlerin tek çatı altında toplanmasını', ['Saltanatın kaldırılmasını', 'Düzenli ordunun kurulmasını', 'Batı Cephesi\'nde ilk zaferin kazanılmasını'], 'Bölgesel cemiyetlerin tek ad altında birleşmesi, dağınık direnişin örgütsel bütünlüğe kavuşmasını sağlamıştır.'),
  ('Son Osmanlı Mebusan Meclisi\'nin 28 Ocak 1920\'de kabul ettiği ve Millî Mücadele\'nin sınırlarını ve hedeflerini belirleyen belge hangisidir?', 'Misak-ı Millî', ['Amasya Protokolü', 'Teşkilât-ı Esasiye Kanunu', 'Tekâlif-i Milliye Emirleri'], 'Misak-ı Millî (Millî Ant), Son Osmanlı Mebusan Meclisi\'nde gizli oturumda kabul edilmiş ve 17 Şubat 1920\'de kamuoyuna duyurulmuştur.'),
  ('İstanbul\'un resmen işgali sırasında tutuklanarak sürgün edilen bazı milletvekilleri ve aydınlar nereye gönderilmiştir?', 'Malta Adası\'na', ['Kıbrıs\'a', 'Rodos\'a', 'Girit Adası\'na'], 'İngilizler, Rauf Orbay ve Ziya Gökalp gibi pek çok aydını ve milletvekilini tutuklayarak Malta\'ya sürgün etmiştir; bunlar daha sonra esir değişimiyle dönmüştür.'),
  ('TBMM 23 Nisan 1920\'de açıldığında kabul ettiği "Meclisin üstünde bir güç yoktur" ilkesi aşağıdakilerden hangisini ifade eder?', 'Millî egemenliği', ['Kuvvetler ayrılığını', 'Laikliği', 'Devletçiliği'], 'TBMM\'nin üstünde bir gücün tanınmaması, egemenliğin millete ait olduğunun ve meclisin bu egemenliği temsil ettiğinin göstergesidir.'),
  ('I. TBMM\'nin yasama, yürütme ve yargı yetkilerini kendinde toplaması hangi yönetim anlayışını yansıtır?', 'Güçler birliği', ['Güçler ayrılığı', 'Başkanlık sistemi', 'Mutlak monarşi'], 'I. TBMM olağanüstü şartlar nedeniyle bütün yetkileri kendinde toplamış; bu meclis hükümeti sistemi güçler birliği ilkesine dayanır.'),
  ('I. TBMM\'nin ilk başkanı kimdir?', 'Mustafa Kemal Paşa', ['Fevzi Çakmak', 'Celalettin Arif', 'Hüseyin Rauf'], 'Mustafa Kemal, 24 Nisan 1920\'de TBMM Başkanı seçilmiştir; meclis başkanı aynı zamanda hükümetin de başkanıydı.'),
  ('Önce Kuvâ-yı Milliye\'de önemli hizmetler yapan, ancak düzenli orduya katılmayı reddederek TBMM\'ye karşı ayaklanan ve sonunda Yunanlılara sığınan kişi kimdir?', 'Çerkez Ethem', ['Demirci Mehmet Efe', 'Yörük Ali Efe', 'Ahmet Anzavur'], 'Çerkez Ethem, Kuvâ-yı Seyyare komutanıyken düzenli orduya bağlanmayı kabul etmemiş, ayaklanmış ve yenilince Yunan tarafına geçmiştir.'),
  ('Sevr Antlaşması 10 Ağustos 1920\'de hangi şehirde imzalanmıştır?', 'Paris yakınlarındaki Sevr kasabasında', ['Londra\'da', 'Roma\'da', 'İsviçre\'nin Cenevre şehrinde'], 'Antlaşma, Paris yakınlarındaki Sèvres kasabasında İstanbul hükümeti temsilcileri ile İtilaf Devletleri arasında imzalanmıştır.'),
  ('Doğu Cephesi\'nde Ermenilere karşı başarılı harekâtı yöneten ve Gümrü Antlaşması\'nı imzalatan komutan kimdir?', 'Kâzım Karabekir', ['Ali Fuat Cebesoy', 'Refet Bele', 'Nurettin Paşa'], '15. Kolordu Komutanı Kâzım Karabekir, 1920\'deki harekâtla Kars\'ı almış ve 3 Aralık 1920\'de Gümrü Antlaşması imzalanmıştır.'),
  ('TBMM, savunmalarındaki üstün başarıları nedeniyle üç güney şehrine unvan vermiştir. Antep\'e verilen unvan aşağıdakilerden hangisidir?', 'Gazi', ['Kahraman', 'Şanlı', 'Yiğit'], 'Antep\'e "Gazi", Maraş\'a "Kahraman", Urfa\'ya ise "Şanlı" unvanı verilmiştir.'),
  ('Güney Cephesi\'nde Fransızlarla süren mücadele hangi antlaşmayla sona ermiştir?', 'Ankara Antlaşması', ['Mudanya Ateşkes Antlaşması', 'Kars Antlaşması', 'Lozan Antlaşması'], '20 Ekim 1921\'de imzalanan Ankara Antlaşması ile Fransa Güney Cephesi\'nden çekilmiş ve TBMM\'yi tanımıştır.'),
  ('Antep savunmasında şehit düşen ve adı bugün bir kahramanlık simgesi olan Kuvâ-yı Milliye önderi kimdir?', 'Şahin Bey', ['Sütçü İmam', 'Hasan Tahsin', 'Yörük Ali Efe'], 'Şahin Bey, Antep\'e gelen Fransız takviye kuvvetlerine karşı Ayıntap yolunda direnmiş ve 1920\'de şehit olmuştur.'),
  ('Kuvâ-yı Milliye birliklerinin Yunan ilerleyişini tam olarak durduramaması TBMM\'yi hangi karara yöneltmiştir?', 'Düzenli ordunun kurulmasına', ['İstanbul hükümetiyle birleşmeye', 'Manda yönetimini kabul etmeye', 'Başkenti Sivas\'a taşımaya'], 'Kuvâ-yı Milliye disiplin ve merkezî komuta açısından yetersiz kalınca 1920 sonlarında düzenli ordu kurulmuştur.'),
  ('Düzenli ordunun Yunanlılara karşı kazandığı ilk zafer hangisidir?', 'I. İnönü Muharebesi', ['Sakarya Meydan Muharebesi', 'II. İnönü Muharebesi', 'Dumlupınar Meydan Muharebesi'], 'Ocak 1921\'de İsmet Bey komutasında kazanılan I. İnönü Muharebesi, düzenli ordunun ilk zaferidir.'),
  ('I. İnönü Muharebesi\'nden sonra TBMM\'nin kabul ettiği ilk anayasa hangisidir?', '1921 Teşkilât-ı Esasiye Kanunu', ['Kanun-ı Esasi', '1924 Teşkilât-ı Esasiye Kanunu', 'Islahat Fermanı\'na dayanan yönetim belgesi'], '20 Ocak 1921\'de kabul edilen Teşkilât-ı Esasiye Kanunu, TBMM\'nin hazırladığı ilk anayasadır ve I. İnönü zaferinin hemen ardından kabul edilmiştir.'),
  ('Mustafa Kemal\'in, İsmet Paşa\'ya çektiği "Siz orada yalnız düşmanı değil, milletin makûs talihini de yendiniz" telgrafı hangi zaferden sonra gönderilmiştir?', 'II. İnönü Muharebesi', ['I. İnönü Muharebesi', 'Sakarya Meydan Muharebesi', 'Afyon-Dumlupınar Meydan Muharebesi'], 'Mart-Nisan 1921\'deki II. İnönü zaferinden sonra Mustafa Kemal bu ünlü telgrafı İsmet Paşa\'ya göndermiştir.'),
  ('Millî Mücadele döneminde Türk halkının söz birliğini ve TBMM\'ye bağlılığını sembolleştirmek için 12 Mart 1921\'de kabul edilen metin hangisidir?', 'İstiklal Marşı', ['Misak-ı Millî', 'Gençliğe Hitabe', 'Nutuk'], 'Mehmet Âkif Ersoy\'un yazdığı İstiklal Marşı, TBMM\'nin açtığı yarışma sonucunda 12 Mart 1921\'de millî marş olarak kabul edilmiştir.'),
  ('Kütahya-Eskişehir yenilgisinden sonra Mustafa Kemal\'e meclisin bütün yetkilerini üç ay süreyle kullanma hakkı veren kanun hangisidir?', 'Başkomutanlık Kanunu', ['Takrir-i Sükûn Kanunu', 'Hıyanet-i Vataniye Kanunu', 'Teşkilât-ı Esasiye Kanunu'], '5 Ağustos 1921\'de çıkarılan Başkomutanlık Kanunu ile Mustafa Kemal, meclis adına geniş yetkilerle başkomutan olmuştur.'),
  ('Sakarya Meydan Muharebesi\'nde Mustafa Kemal\'in verdiği "Hatt-ı müdafaa yoktur, sath-ı müdafaa vardır" emri hangi savunma anlayışını ifade eder?', 'Bütün yurt toprağının karış karış savunulması', ['Savunmanın yalnız tahkimatlı hatlarda yapılması', 'Ordunun hemen Ankara\'ya çekilmesi', 'Savaşın denize taşınması'], 'Bu emir, belirli bir çizginin değil bütün vatanın savunulacağını; her birliğin bulunduğu yerde direneceğini ifade eder.'),
  ('Sakarya Meydan Muharebesi\'nden sonra TBMM\'nin Mustafa Kemal\'e verdiği rütbe ve unvan hangisidir?', 'Mareşallik rütbesi ve Gazi unvanı', ['Orgenerallik rütbesi ve Atatürk soyadı', 'Başkomutanlık ve Paşa unvanı', 'Tümgenerallik ve Müşir unvanı'], 'Sakarya zaferinden sonra Mustafa Kemal\'e 19 Eylül 1921\'de mareşal rütbesi ve gazi unvanı verilmiştir.'),
  ('Büyük Taarruz 26 Ağustos 1922\'de hangi bölgeden başlamıştır?', 'Afyon\'un güneyindeki Kocatepe\'den', ['Eskişehir\'in kuzeyindeki Sakarya\'dan', 'Kütahya\'nın doğusundaki Dumlupınar\'dan', 'Bursa\'nın güneyindeki Uludağ\'dan'], 'Mustafa Kemal Büyük Taarruz\'u Kocatepe\'den yönetmiş; taarruz 26 Ağustos 1922 sabahı başlamıştır.'),
  ('Büyük Taarruz sırasında 30 Ağustos 1922\'de yapılan ve Yunan ordusunun ana gövdesinin imha edildiği muharebe hangisidir?', 'Başkomutan Meydan Muharebesi', ['Sakarya Meydan Muharebesi', 'Kütahya Muharebesi', 'Afyon Kalesi Muharebesi'], 'Dumlupınar\'daki Başkomutan Meydan Muharebesi\'nde Yunan ordusu büyük bir yenilgiye uğratılmıştır; 30 Ağustos bugün Zafer Bayramı olarak kutlanır.'),
  ('Mudanya Ateşkes Antlaşması\'nda TBMM\'yi temsil eden kişi kimdir?', 'İsmet Paşa', ['Rauf Bey', 'Fevzi Paşa', 'Refet Bele Paşa'], 'Mudanya görüşmelerinde TBMM\'yi Batı Cephesi Komutanı İsmet Paşa temsil etmiş; İngiltere\'yi General Harington temsil etmiştir.'),
  ('Mudanya Ateşkesi\'nin İstanbul açısından sonucu ne olmuştur?', 'Yönetiminin TBMM\'ye bırakılması', ['Uluslararası bir şehir ilan edilmesi', 'Yunan yönetimine verilmesi', 'Milletler Cemiyeti\'ne devredilmesi'], 'Mudanya ile İstanbul ve Boğazların yönetimi TBMM\'ye bırakılmış; ancak İtilaf kuvvetleri barış imzalanana kadar şehirde kalmıştır.'),
  ('Saltanatın kaldırılmasından sonra İngiliz zırhlısıyla İstanbul\'dan ayrılan son Osmanlı padişahı kimdir?', 'VI. Mehmed Vahdeddin', ['V. Mehmed Reşad Efendi', 'II. Abdülhamid', 'Abdülmecid Efendi'], 'VI. Mehmed Vahdeddin, 17 Kasım 1922\'de Malaya zırhlısıyla İstanbul\'dan ayrılmıştır. Ardından TBMM, Abdülmecid Efendi\'yi yalnızca halife olarak seçmiştir.'),
  ('Lozan Konferansı\'nda Türk heyetinin başkanı kimdir?', 'İsmet Paşa', ['Rauf Bey', 'Rıza Nur', 'Hasan Saka Bey'], 'Lozan\'da Türk heyetine İsmet Paşa başkanlık etmiş; Rıza Nur ve Hasan Saka danışman ve delege olarak yer almıştır.'),
  ('Lozan Konferansı\'nda çözüme bağlanamayan ve sonradan İngiltere ile ikili görüşmelere bırakılan sorun hangisidir?', 'Irak sınırı', ['Kapitülasyonlar', 'Boğazlar', 'Osmanlı borçları'], 'Musul sorunu Lozan\'da çözülemeyince Türkiye ile İngiltere arasında ikili görüşmelere bırakılmış; 1926 Ankara Antlaşması ile Musul Irak\'a bırakılmıştır.'),
  ('Lozan Antlaşması\'nın Sevr\'den temel farkı aşağıdakilerden hangisidir?', 'Türk milletinin bağımsızlığını uluslararası alanda tescil etmesi', ['Yalnızca askerî konuları ve ateşkes sınırlarını düzenlemesi', 'Osmanlı hanedanını yeniden tanıması', 'Türkiye\'ye manda yönetimi getirmesi'], 'Sevr, Türklerin bağımsızlığını ortadan kaldıran bir paylaşım belgesi iken Lozan, yeni Türk devletinin tam bağımsızlığının tescili olmuştur.'),
  ('Cumhuriyetin ilanıyla birlikte ilk cumhurbaşkanı ve ilk başbakan olarak kimler seçilmiştir?', 'Mustafa Kemal ve İsmet Paşa', ['Mustafa Kemal ve Fethi Bey', 'İsmet Paşa ve Celal Bayar', 'Mustafa Kemal ve Rauf Bey'], '29 Ekim 1923\'te Mustafa Kemal cumhurbaşkanı seçilmiş, ilk hükümeti kurma görevi İsmet Paşa\'ya verilmiştir.'),
  ('Cumhuriyetin ilanından önce, 13 Ekim 1923\'te alınan karar hangisidir?', 'Ankara\'nın başkent olması', ['Saltanatın kaldırılması', 'Halifeliğin kaldırılması', 'Türk Medeni Kanunu\'nun kabulü'], 'Ankara, 13 Ekim 1923\'te kabul edilen kanunla yeni Türk devletinin başkenti olmuştur.'),
  ('3 Mart 1924\'te halifeliğin kaldırılmasıyla aynı gün kabul edilen kanunlardan biri aşağıdakilerden hangisidir?', 'Tevhid-i Tedrisat Kanunu', ['Soyadı Kanunu', 'Şapka Kanunu', 'Türk Medeni Kanunu'], '3 Mart 1924\'te halifeliğin kaldırılması, Tevhid-i Tedrisat Kanunu ve Şer\'iye ve Evkaf Vekâleti\'nin kaldırılması kabul edilmiştir.'),
  ('Halifeliğin kaldırılmasıyla Osmanlı hanedanı üyelerine ilişkin alınan karar aşağıdakilerden hangisidir?', 'Yurt dışına çıkarılmaları', ['Meclise milletvekili olarak alınmaları', 'Ankara\'da yaşamaya zorlanmaları', 'Fahri yurttaş ilan edilmeleri'], '3 Mart 1924 kanunlarıyla Osmanlı hanedanı üyeleri yurt dışına çıkarılmıştır.'),
  ('1924 Anayasası\'nda 1934\'te yapılan değişiklikle hangi hak anayasal güvenceye kavuşmuştur?', 'Kadınların milletvekili seçme ve seçilme hakkı', ['Toplu sözleşme ve grev hakkı', 'Anayasa Mahkemesi\'ne bireysel başvuru hakkı', 'Üniversitelerin özerkliği'], '5 Aralık 1934\'te yapılan anayasa değişikliğiyle Türk kadınlarına milletvekili seçme ve seçilme hakkı tanınmıştır.'),
  ('Türkiye Cumhuriyeti\'nin ilk muhalefet partisi olan Terakkiperver Cumhuriyet Fırkası 1924\'te kimlerin öncülüğünde kurulmuştur?', 'Kâzım Karabekir ve arkadaşları', ['Fethi Okyar ve Celal Bayar ile arkadaşları', 'İsmet İnönü ve Recep Peker ile arkadaşları', 'Adnan Menderes ve Refik Koraltan ile arkadaşları'], 'Kâzım Karabekir, Rauf Orbay, Ali Fuat Cebesoy ve Refet Bele gibi isimler 17 Kasım 1924\'te Terakkiperver Cumhuriyet Fırkası\'nı kurmuştur.'),
  ('Serbest Cumhuriyet Fırkası\'nın kurucusu ve genel başkanı kimdir?', 'Ali Fethi Okyar', ['Kâzım Karabekir Paşa', 'Celal Bayar', 'Refik Saydam'], 'Serbest Cumhuriyet Fırkası 12 Ağustos 1930\'da Ali Fethi Okyar tarafından kurulmuş, aynı yılın kasım ayında kendini feshetmiştir.'),
  ('1925 Şeyh Said İsyanı\'nın ardından hükümete olağanüstü yetkiler veren kanun hangisidir?', 'Takrir-i Sükûn Kanunu', ['Teşvik-i Sanayi Kanunu', 'Hıyanet-i Vataniye Kanunu', 'Tevhid-i Tedrisat Kanunu'], '4 Mart 1925\'te çıkarılan Takrir-i Sükûn Kanunu, hükümete isyan ve kargaşaya yol açacak örgüt ve yayınları kapatma yetkisi vermiştir.'),
  ('1926\'da Atatürk\'e yönelik suikast girişimi hangi şehirde ortaya çıkarılmıştır?', 'İzmir', ['Bursa', 'Ankara', 'Konya'], 'Haziran 1926\'da İzmir\'de Atatürk\'e düzenlenmek istenen suikast girişimi ortaya çıkarılmış ve sorumlular İstiklal Mahkemesi\'nde yargılanmıştır.'),
  ('1930\'daki Menemen Olayı\'nda inkılap karşıtlarınca şehit edilen yedek subay öğretmen kimdir?', 'Mustafa Fehmi Kubilay', ['Hasan Tahsin', 'Mehmet Çavuş', 'Sütçü İmam Hasan Efendi'], '23 Aralık 1930\'da Menemen\'de Derviş Mehmet ve yandaşları, ayaklanmayı engellemeye çalışan Asteğmen Kubilay\'ı şehit etmiştir.'),
  ('1926\'da kabul edilen Türk Medeni Kanunu hangi ülkenin medeni kanunu örnek alınarak hazırlanmıştır?', 'İsviçre', ['Almanya İmparatorluğu', 'Fransa', 'İtalya'], 'Türk Medeni Kanunu, İsviçre Medeni Kanunu esas alınarak hazırlanmış ve 17 Şubat 1926\'da kabul edilmiştir.'),
  ('1 Kasım 1928\'de kabul edilen kanunla Türkiye\'de hangi değişiklik yapılmıştır?', 'Latin harflerine dayalı yeni Türk alfabesi kabul edilmiştir', ['Hicri takvim yerine miladi takvim resmî olarak kabul edilmiştir', 'Soyadı kullanılması zorunlu tutulmuştur', 'Uluslararası ölçü birimleri benimsenmiştir'], 'Harf İnkılabı ile Arap harfleri yerine Latin kökenli yeni Türk harfleri kabul edilmiş; okuma-yazmayı kolaylaştırmak amaçlanmıştır.'),
  ('Yeni harflerin halka hızla öğretilmesi amacıyla 1929\'da açılan ve Atatürk\'ün başöğretmen olduğu kurumlar hangileridir?', 'Millet Mektepleri', ['Köy Enstitüleri', 'Halkevleri', 'Darülfünun şubeleri'], 'Millet Mektepleri, okuma-yazma bilmeyen yetişkinlere yeni harfleri öğretmek için açılmış; Atatürk\'e "Başöğretmen" unvanı verilmiştir.'),
  ('1933 Üniversite Reformu ile kapatılıp yerine İstanbul Üniversitesi kurulan kurum hangisidir?', 'Darülfünun', ['Mekteb-i Mülkiye', 'Enderun Mektebi', 'Darüşşafaka'], 'Bilimsel gelişmelere ayak uyduramadığı düşünülen Darülfünun 1933\'te kapatılmış, yerine İstanbul Üniversitesi kurulmuştur; Almanya\'dan kaçan birçok bilim insanı burada görev almıştır.'),
  ('1925\'te kabul edilen Şapka Kanunu\'nun amacı aşağıdakilerden hangisidir?', 'Kılık kıyafette çağdaş bir görünüm sağlamak', ['Yerli kumaş ve şapka üretimini artırmak', 'Ordunun üniformalarını değiştirmek', 'Din adamlarının kıyafetlerini belirlemek'], 'Şapka Kanunu, toplumsal hayatta Batılı ve çağdaş bir görünüm kazandırmayı amaçlamıştır; Atatürk şapkayı ilk kez Kastamonu gezisinde tanıtmıştır.'),
  ('Tekke, zaviye ve türbelerin kapatılmasıyla hangi ilkenin uygulanması amaçlanmıştır?', 'Laiklik', ['Devletçilik', 'Halkçılık', 'Cumhuriyetçilik'], '1925\'te tekke ve zaviyelerin kapatılması ve unvanların kaldırılması, din ile devlet işlerinin ayrılması ve toplumsal hayatın laikleşmesi amacına hizmet etmiştir.'),
  ('Mustafa Kemal\'e "Atatürk" soyadı TBMM tarafından hangi yıl verilmiştir?', '1934', ['1923', '1928', '1938'], 'Soyadı Kanunu\'nun ardından 24 Kasım 1934\'te çıkarılan özel bir kanunla Mustafa Kemal\'e "Atatürk" soyadı verilmiştir.'),
  ('1935\'te kabul edilen bir düzenlemeyle hafta tatili hangi güne alınmıştır?', 'Pazar', ['Cuma', 'Cumartesi', 'Perşembe'], '1935\'te çıkarılan kanunla hafta tatili cuma gününden pazar gününe alınmış; bu Batı ile ticari ilişkileri kolaylaştırmıştır.'),
  ('Dünyanın ilk kadın savaş pilotu olarak kabul edilen Türk havacı kimdir?', 'Sabiha Gökçen', ['Bedriye Tahir Gökmen', 'Vecihe Gökçe Dayıoğlu', 'Leman Bozkurt Altınçekiç'], 'Atatürk\'ün manevi kızı Sabiha Gökçen, 1937 Dersim harekâtına katılarak dünyanın ilk kadın savaş pilotu olarak tarihe geçmiştir.'),
  ('Atatürk\'ün "Bir toplum, bir millet, erkek ve kadın denilen iki cins insandan mürekkeptir. Kabil midir ki bir kütlenin bir parçasını ilerletelim, ötekini ihmal edelim" sözü hangi düşünceyi savunur?', 'Toplumsal kalkınmada kadın ile erkeğin birlikte ilerlemesi', ['Kadınların yalnızca ev işleriyle sınırlı kalması', 'Eğitimin yalnız erkeklere yönelik olması', 'Kadın haklarının tümüyle din kurallarına ve geleneklere bırakılması'], 'Atatürk bu sözle kadını ihmal eden bir toplumun yarım kalacağını vurgular; inkılaplar bu nedenle kadınların eğitim ve siyasi haklarını da kapsamıştır.'),
  ('İzmir İktisat Kongresi\'nde alınan kararlarla hazırlanan ve "Türkiye\'nin ekonomik anayasası" niteliği taşıyan metin hangisidir?', 'Misak-ı İktisadi', ['Teşvik-i Sanayi Kanunu', 'Aşar Vergisi Kararnamesi', 'Kabotaj Kanunu'], 'Kongrede kabul edilen Misak-ı İktisadi (İktisat Andı), ekonomik bağımsızlık ve millî ekonomi ilkelerini belirleyen belge olmuştur.'),
  ('1925\'te aşar vergisinin kaldırılmasının amaçlarından biri aşağıdakilerden hangisidir?', 'Köylünün üzerindeki ağır yükü hafifletmek', ['Sanayicilerden daha fazla vergi almak', 'Dış borçları ödemek için yeni bir gelir kaynağı yaratmak', 'Tarım arazilerini devletleştirmek'], 'Ürünün onda birinin vergi olarak alındığı aşar, köylüyü yoksullaştırıyordu; kaldırılması tarımın canlanmasını ve köylünün rahatlamasını amaçlamıştır.'),
  ('Sümerbank ve Etibank\'ın 1930\'larda kurulması ekonomide hangi politikanın yansımasıdır?', 'Devletçilik', ['Liberalizm', 'Merkantilizm', 'Kapitülasyon'], 'Sümerbank (1933) dokuma ve sanayi, Etibank (1935) madencilik yatırımları için kurulmuş devlet kuruluşlarıdır; bunlar devletçilik politikasının ürünleridir.'),
  ('Atatürk ilkelerinden hangisi "egemenliğin millete ait olduğu ve yöneticilerin seçimle belirlendiği yönetim biçimini" ifade eder?', 'Cumhuriyetçilik', ['İnkılapçılık', 'Devletçilik', 'Milliyetçilik ilkesi'], 'Cumhuriyetçilik, millî egemenliğe dayanan ve devlet başkanının seçimle iş başına geldiği yönetim anlayışıdır.'),
  ('"Hiçbir kişiye, aileye, zümreye ya da sınıfa ayrıcalık tanımamak" anlayışı Atatürk ilkelerinden hangisinin özüdür?', 'Halkçılık', ['Laiklik', 'Cumhuriyetçilik', 'İnkılapçılık'], 'Halkçılık, toplumda kanun önünde eşitliği ve sınıf ayrıcalığının reddini savunur; unvanların kaldırılması ve Medeni Kanun bu ilkeyle ilişkilidir.'),
  ('Atatürk ilkelerinden inkılapçılığın temel amacı aşağıdakilerden hangisidir?', 'Yapılan inkılapları korumak ve çağın gereklerine göre geliştirmek', ['Ekonomide devletin rolünü sınırlamak', 'Dış politikada yalnızlığı tercih etmek', 'Geleneksel kurumları hiç değiştirmeden yaşatmak ve korumak'], 'İnkılapçılık, gerçekleştirilen yenilikleri korumayı ve toplumu sürekli çağdaşlaştırmayı öngören dinamik bir ilkedir.'),
  ('Atatürk ilkeleri 1937\'de hangi belgeye eklenerek anayasal nitelik kazanmıştır?', '1924 Anayasası', ['1921 Anayasası', '1961 Anayasası', 'Misak-ı Millî'], 'Altı ilke 1931\'de Cumhuriyet Halk Fırkası programına girmiş, 5 Şubat 1937\'de ise 1924 Anayasası\'na eklenmiştir.'),
  ('Bir öğrenci, "Akla ve bilime dayanma, dogmalara bağlı kalmama" anlayışının bütün Atatürk ilkelerinin ortak dayanağı olduğunu söylemektedir. Öğrencinin vurguladığı temel düşünce hangisidir?', 'Akılcılık ve bilimsellik', ['Ümmetçilik', 'Bölgecilik', 'Gelenekçilik ve muhafazakârlık'], 'Atatürk "Hayatta en hakiki mürşit ilimdir" sözüyle de ifade ettiği gibi bütün ilkeleri akıl ve bilime dayandırmıştır; bu nedenle akılcılık ilkelerin ortak temeli sayılır.'),
  ('1937\'de Türkiye, İran, Irak ve Afganistan arasında imzalanan saldırmazlık paktı hangisidir?', 'Sadabad Paktı', ['Bağdat Paktı', 'Balkan Antantı Paktı', 'Varşova Paktı'], 'Tahran\'daki Sadabad Sarayı\'nda imzalanan pakt, doğu komşularıyla iyi ilişkileri güçlendirmiş ve İtalya\'nın Orta Doğu\'ya yönelik tehdidine karşı bir güvence olmuştur.'),
  ('Montrö Boğazlar Sözleşmesi 1936\'da Türkiye\'ye hangi hakkı kazandırmıştır?', 'Boğazlarda tam egemenlik ve asker bulundurma hakkı', ['Boğazlardan geçen gemilerden sınırsız vergi alma hakkı', 'Boğazları her koşulda bütün gemilere kapatma hakkı', 'Ege adalarının tamamını silahlandırma hakkı'], 'Montrö ile Boğazlar Komisyonu kaldırılmış, Boğazların yönetimi Türkiye\'ye geçmiş ve bölgeyi silahlandırma hakkı tanınmıştır.'),
  ('Atatürk\'ün "Hatay benim şahsi meselemdir" demesi bu sorunun nasıl görüldüğünü gösterir?', 'Millî bir dava olarak', ['Yalnızca ekonomik bir sorun olarak', 'Fransa\'ya bırakılabilecek bir konu olarak', 'Uluslararası bir ticaret meselesi olarak'], 'Atatürk, Hatay\'ın Türk yurdu olduğunu vurgulayarak sorunu millî bir dava hâline getirmiş ve hasta olmasına rağmen yakından takip etmiştir.'),
  ('Atatürk\'ün "Yurtta sulh, cihanda sulh" sözü dış politikada hangi yaklaşımı ifade eder?', 'Barışçı ve statükocu bir politika', ['Yayılmacı ve saldırgan bir politika', 'Tamamen yalnızlıkçı bir politika', 'Bloklardan birine bağımlı bir politika'], 'Bu söz, Türkiye\'nin hem içte hem dışta barışı esas aldığını ve mevcut sınırları korumayı hedeflediğini gösterir.'),
  ('Mustafa Kemal hangi yıl ve nerede doğmuştur?', '1881, Selanik', ['1880, Manastır', '1882, İstanbul', '1879, Edirne'], 'Mustafa Kemal 1881\'de Selanik\'te, Ali Rıza Efendi ile Zübeyde Hanım\'ın oğlu olarak doğmuştur.'),
  ('Mustafa Kemal\'in Çanakkale\'de 57. Alay\'a verdiği "Ben size taarruz emretmiyorum, ölmeyi emrediyorum" emri hangi cephede verilmiştir?', 'Arıburnu', ['Seddülbahir', 'Kumkale', 'Kilitbahir'], '25 Nisan 1915\'te Arıburnu\'na çıkan İtilaf kuvvetlerine karşı Mustafa Kemal, Conkbayırı yönünde 57. Alay\'a bu emri vermiştir.'),
  ('Atatürk\'ün 1927\'de CHP Kurultayı\'nda okuduğu ve 1919-1927 arasını anlattığı eser hangisidir?', 'Nutuk', ['Geometri', 'Zabit ve Kumandan ile Hasbıhal', 'Gençliğe Hitabe kitabı'], 'Nutuk, 15-20 Ekim 1927 tarihlerinde altı günde okunmuş ve Millî Mücadele ile Cumhuriyet\'in ilk yıllarını Atatürk\'ün gözünden anlatmıştır.'),
  ('Atatürk hangi tarihte, nerede hayatını kaybetmiştir?', '10 Kasım 1938, İstanbul Dolmabahçe Sarayı', ['10 Kasım 1937, Ankara Çankaya Köşkü', '29 Ekim 1938, Ankara Çankaya Köşkü', '10 Kasım 1938, Ankara Etnografya Müzesi\'ndeki oda'], 'Atatürk 10 Kasım 1938\'de İstanbul\'daki Dolmabahçe Sarayı\'nda vefat etmiş; naaşı 1953\'te Anıtkabir\'e nakledilene kadar Ankara Etnografya Müzesi\'nde kalmıştır.'),
  ('Atatürk\'ün "Muhtaç olduğun kudret damarlarındaki asil kanda mevcuttur" sözüyle sona eren ünlü metni kime seslenir?', 'Türk gençliğine', ['Türk ordusuna', 'Türk öğretmenlerine', 'Türk köylüsüne'], 'Gençliğe Hitabe, Nutuk\'un sonunda yer alır ve cumhuriyeti koruma görevini Türk gençliğine emanet eder.'),
  ('Atatürk\'ün ölümünden sonra cumhurbaşkanı seçilen ve "Millî Şef" olarak anılan devlet adamı kimdir?', 'İsmet İnönü', ['Celal Bayar', 'Fevzi Çakmak', 'Refik Saydam'], 'İsmet İnönü 11 Kasım 1938\'de cumhurbaşkanı seçilmiş, aynı zamanda CHP\'nin değişmez genel başkanı ve "Millî Şef" olmuştur.'),
  ('II. Dünya Savaşı sırasında Türkiye\'nin izlediği temel politika aşağıdakilerden hangisidir?', 'Savaşa girmeden denge politikası izlemek', ['Mihver Devletleri\'nin yanında savaşa katılmak', 'Savaşın başında Sovyetlere savaş açmak', 'Balkanlarda toprak kazanmak için sefer düzenlemek'], 'Türkiye savaş boyunca iki tarafla da ilişkilerini dengeleyerek savaş dışı kalmayı başarmış; yalnızca Şubat 1945\'te sembolik olarak Almanya ve Japonya\'ya savaş ilan etmiştir.'),
  ('1940\'ta kurulan ve köy çocuklarını öğretmen olarak yetiştirip köylerine geri göndermeyi amaçlayan kurumlar hangileridir?', 'Köy Enstitüleri', ['Halkevleri', 'Millet Mektepleri', 'Darülmuallimin'], 'Hasan Âli Yücel ve İsmail Hakkı Tonguç\'un öncülüğünde kurulan Köy Enstitüleri, uygulamalı eğitimle köy öğretmeni yetiştirmiştir.'),
  ('Türkiye\'de çok partili hayata kalıcı geçişi başlatan Demokrat Parti\'yi 1946\'da kuran dört kişi arasında aşağıdakilerden hangisi yoktur?', 'Fethi Okyar', ['Celal Bayar', 'Adnan Menderes', 'Fuat Köprülü'], 'Demokrat Parti, Dörtlü Takrir\'i veren Celal Bayar, Adnan Menderes, Refik Koraltan ve Fuat Köprülü tarafından 7 Ocak 1946\'da kurulmuştur.'),
  ('14 Mayıs 1950 seçimlerinin sonucu aşağıdakilerden hangisidir?', 'Demokrat Parti\'nin iktidara gelmesi', ['CHP\'nin oylarını artırarak iktidarda kalması', 'Seçimlerin ordu tarafından iptal edilmesi', 'Hiçbir partinin meclise girememesi'], '1950 seçimlerini DP kazanmış; Celal Bayar cumhurbaşkanı, Adnan Menderes başbakan olmuş ve iktidar ilk kez seçimle el değiştirmiştir.'),
  ('Türkiye NATO\'ya hangi yıl üye olmuştur?', '1952', ['1949', '1955', '1947'], 'Türkiye, Yunanistan ile birlikte 18 Şubat 1952\'de NATO\'ya katılmıştır. NATO 1949\'da kurulmuştur.'),
  ('27 Mayıs 1960 askerî müdahalesinin ardından yönetimi üstlenen ve Cemal Gürsel\'in başkanlık ettiği kurul hangisidir?', 'Millî Birlik Komitesi', ['Millî Güvenlik Konseyi', 'Danışma Meclisi', 'Temsilciler Meclisi'], '27 Mayıs 1960\'tan sonra yönetimi Millî Birlik Komitesi üstlenmiş; 1980 müdahalesinde ise Millî Güvenlik Konseyi kurulmuştur.'),
  ('1974 Kıbrıs Barış Harekâtı\'nın kararını veren hükümetin başbakanı kimdir?', 'Bülent Ecevit', ['Süleyman Demirel', 'Necmettin Erbakan', 'Nihat Erim'], 'Harekât, Bülent Ecevit başkanlığındaki CHP-MSP koalisyon hükümeti döneminde gerçekleştirilmiştir.'),
  ('1983\'te ilan edilen ve yalnızca Türkiye tarafından tanınan devlet hangisidir?', 'Kuzey Kıbrıs Türk Cumhuriyeti', ['Kıbrıs Türk Federe Devleti', 'Kıbrıs Türk Geçici Yönetimi', 'Kıbrıs Türk Yönetimi'], '15 Kasım 1983\'te Rauf Denktaş önderliğinde KKTC ilan edilmiştir. 1975\'te kurulan Kıbrıs Türk Federe Devleti onun öncülüdür.'),
  ('12 Eylül 1980 askerî müdahalesinden sonra hazırlanan 1982 Anayasası halkoylamasıyla kabul edilmiştir. Aynı oylamada cumhurbaşkanı olan kişi kimdir?', 'Kenan Evren', ['Turgut Özal', 'Fahri Korutürk', 'Cevdet Sunay'], '7 Kasım 1982 halkoylamasıyla anayasa kabul edilmiş ve Kenan Evren yedi yıllık süre için cumhurbaşkanı olmuştur.'),
  ('1983 genel seçimlerini kazanarak tek başına iktidara gelen parti ve lideri hangisidir?', 'Anavatan Partisi, Turgut Özal', ['Doğru Yol Partisi, Süleyman Demirel', 'Halkçı Parti, Necdet Calp', 'Milliyetçi Demokrasi Partisi, Turgut Sunalp'], '1983 seçimlerini Turgut Özal\'ın ANAP\'ı kazanmıştır; seçimlere yalnızca Millî Güvenlik Konseyi\'nin izin verdiği üç parti katılabilmiştir.'),
  ('I. Dünya Savaşı\'nın başlamasına yol açan Saraybosna suikastında öldürülen kişi kimdir?', 'Avusturya-Macaristan veliahtı Franz Ferdinand', ['Rus Çarı II. Nikola ve ailesinin bütün bireyleri', 'Alman İmparatoru II. Wilhelm', 'Sırbistan Kralı I. Petar ile oğlu'], '28 Haziran 1914\'te Sırp milliyetçisi Gavrilo Princip, Arşidük Franz Ferdinand ve eşini Saraybosna\'da öldürmüştür.'),
  ('I. Dünya Savaşı\'nda Rusya\'nın savaştan çekildiği antlaşma hangisidir?', 'Brest-Litovsk', ['Versay', 'Saint-Germain', 'Neuilly-sur-Seine'], 'Bolşevik hükümeti Mart 1918\'de Almanya ve müttefikleriyle Brest-Litovsk Antlaşması\'nı imzalayarak savaştan çekilmiştir.'),
  ('I. Dünya Savaşı\'ndan sonra dünya barışını korumak amacıyla kurulan, ancak ABD\'nin üye olmadığı örgüt hangisidir?', 'Milletler Cemiyeti', ['Birleşmiş Milletler', 'Avrupa Konseyi', 'Kuzey Atlantik Antlaşması Örgütü'], 'Wilson\'un önerisiyle 1920\'de kurulan Milletler Cemiyeti\'ne ABD Senatosu onay vermediği için ABD üye olmamıştır.'),
  ('Siper savaşlarının en kanlı örneklerinden biri olan ve 1916\'da Fransa\'da Almanlarla Fransızlar arasında yaklaşık on ay süren muharebe hangisidir?', 'Verdun Muharebesi', ['Stalingrad Muharebesi', 'El Alamein Muharebesi', 'Midway Muharebesi'], 'Verdun Muharebesi Şubat-Aralık 1916 arasında sürmüş ve iki taraftan yüz binlerce askerin ölümüne yol açmıştır. Diğer seçenekler II. Dünya Savaşı muharebeleridir.'),
  ('Ekim 1917 Devrimi ile Rusya\'da yönetimi ele geçiren partinin lideri kimdir?', 'Lenin', ['Kerenski', 'Stalin', 'Troçki'], 'Lenin önderliğindeki Bolşevikler Ekim 1917\'de Kerenski\'nin geçici hükümetini devirerek yönetimi ele geçirmiştir. Troçki devrimde önemli rol oynamış ama lider Lenin\'dir.'),
  ('1929\'da New York Borsası\'nın çökmesiyle başlayan küresel bunalım hangi adla anılır?', 'Büyük Buhran', ['Petrol Krizi', 'Kara Pazartesi', 'Asya Krizi'], 'Ekim 1929\'da New York Borsası\'nın çöküşüyle başlayan Büyük Buhran, dünya çapında işsizlik, iflas ve ticaretin daralmasına yol açmıştır.'),
  ('ABD Başkanı Franklin D. Roosevelt\'in Büyük Buhran\'a karşı uyguladığı politika hangi adla bilinir?', 'New Deal', ['Marshall Planı', 'Truman Doktrini', 'Monroe Doktrini'], 'New Deal (Yeni Düzen), kamu yatırımları, sosyal güvenlik ve bankacılık düzenlemeleriyle ekonomiye devlet müdahalesini öngörmüştür.'),
  ('İtalya\'da 1922\'deki "Roma Yürüyüşü" ile iktidara gelen faşist lider kimdir?', 'Benito Mussolini', ['Francisco Franco', 'Antonio Salazar', 'Vittorio Emanuele'], 'Mussolini, Kara Gömlekliler\'in Roma Yürüyüşü\'nün ardından Kral III. Vittorio Emanuele tarafından başbakanlığa getirilmiştir.'),
  ('Ağustos 1939\'da Almanya ile Sovyetler Birliği arasında imzalanan ve dünyayı şaşırtan antlaşma hangisidir?', 'Molotov-Ribbentrop Paktı', ['Anti-Komintern Paktı\'nın yenilenmesi', 'Çelik Pakt', 'Locarno Antlaşması'], 'Saldırmazlık paktı olan Molotov-Ribbentrop\'un gizli protokolü Polonya ve Doğu Avrupa\'nın paylaşılmasını öngörüyordu; Almanya bir hafta sonra Polonya\'ya saldırmıştır.'),
  ('II. Dünya Savaşı\'nı başlatan olay aşağıdakilerden hangisidir?', 'Almanya\'nın Polonya\'yı işgali', ['Japonya\'nın Pearl Harbor\'ı bombalaması', 'Almanya\'nın Sovyetler Birliği\'ne saldırması', 'İtalya\'nın Arnavutluk\'u ilhakı'], '1 Eylül 1939\'da Almanya Polonya\'ya saldırmış, İngiltere ve Fransa 3 Eylül\'de Almanya\'ya savaş ilan etmiştir.'),
  ('Almanların II. Dünya Savaşı başında uyguladığı, hızlı zırhlı birlikler ve hava desteğiyle yapılan saldırı taktiği hangi adla bilinir?', 'Yıldırım savaşı', ['Siper savaşı', 'Yıpratma ve kuşatma savaşı', 'Gerilla savaşı'], 'Blitzkrieg; tank, motorlu piyade ve uçakların birlikte kullanılmasıyla düşman hatlarını kısa sürede yarmaya dayanır. Polonya ve Fransa bu taktikle hızla yenilmiştir.'),
  ('Almanya\'nın Haziran 1941\'de Sovyetler Birliği\'ne saldırdığı harekâtın adı nedir?', 'Barbarossa Harekâtı', ['Overlord Harekâtı', 'Deniz Aslanı Harekâtı', 'Torch Harekâtı'], 'Barbarossa Harekâtı 22 Haziran 1941\'de başlamıştır. Overlord Normandiya çıkarması, Deniz Aslanı İngiltere\'ye planlanan çıkarma, Torch ise Kuzey Afrika çıkarmasıdır.'),
  ('Japonya\'nın 7 Aralık 1941\'de Pearl Harbor\'a saldırmasının savaşa en önemli etkisi nedir?', 'ABD\'nin savaşa girmesi', ['Sovyetler Birliği\'nin savaştan çekilmesi', 'İngiltere\'nin Japonya ile barış imzalaması', 'Almanya\'nın Japonya\'ya savaş ilan etmesi ve ittifakı bozması'], 'Pearl Harbor saldırısının ardından ABD Japonya\'ya savaş ilan etmiş, Almanya ve İtalya da ABD\'ye savaş ilan edince savaş tam anlamıyla küreselleşmiştir.'),
  ('II. Dünya Savaşı\'nda Doğu Cephesi\'nde Alman ilerleyişini durduran ve savaşın dönüm noktalarından sayılan muharebe hangisidir?', 'Stalingrad', ['Dunkirk', 'Somme', 'Gelibolu'], '1942-1943 kışında Stalingrad\'da Alman 6. Ordusu kuşatılarak teslim olmuş; bundan sonra Sovyetler batıya doğru ilerlemeye başlamıştır.'),
  ('Müttefiklerin 6 Haziran 1944\'te Fransa\'ya yaptığı ve batıda ikinci cepheyi açan çıkarma nerede gerçekleşmiştir?', 'Normandiya', ['Sicilya', 'Dunkirk', 'Marsilya'], 'D-Day olarak bilinen Normandiya çıkarması (Overlord Harekâtı), Batı Avrupa\'nın Alman işgalinden kurtarılmasının başlangıcıdır.'),
  ('Şubat 1945\'te Roosevelt, Churchill ve Stalin\'in savaş sonrası düzeni görüştüğü konferans hangisidir?', 'Yalta Konferansı', ['Potsdam Konferansı', 'Kahire Konferansı', 'Bandung Konferansı'], 'Yalta\'da Almanya\'nın işgal bölgelerine ayrılması, BM\'nin kurulması ve Sovyetlerin Japonya\'ya savaş açması gibi konular görüşülmüştür.'),
  ('Ağustos 1945\'te atom bombası atılan Japon şehirleri hangileridir?', 'Hiroşima ve Nagazaki', ['Tokyo ve Osaka', 'Kyoto ve Kobe limanı', 'Yokohama ve Sapporo'], 'ABD 6 Ağustos\'ta Hiroşima\'ya, 9 Ağustos\'ta Nagazaki\'ye atom bombası atmış; Japonya kısa süre sonra teslim olmuştur.'),
  ('II. Dünya Savaşı sonrasında Nazi liderlerinin savaş suçları ve insanlığa karşı suçlar nedeniyle yargılandığı mahkemeler hangi şehirde kurulmuştur?', 'Nürnberg', ['Berlin', 'Münih', 'Lahey'], '1945-1946\'da Nürnberg\'de kurulan uluslararası askerî mahkeme, Nazi yöneticilerini yargılamış ve uluslararası ceza hukukunun gelişimine katkı sağlamıştır.'),
  ('Nazi Almanyası\'nın Yahudilere ve diğer gruplara yönelik sistematik soykırımı hangi adla anılır?', 'Holokost', ['Kristal Gece', 'Gulag', 'Anschluss'], 'Holokost\'ta yaklaşık altı milyon Yahudi öldürülmüştür. Kristal Gece 1938\'deki bir saldırı dalgası, Anschluss ise Avusturya\'nın ilhakıdır; Gulag Sovyet çalışma kamplarıdır.'),
  ('Almanya\'nın 1938\'de Avusturya\'yı topraklarına katması hangi adla bilinir?', 'Anschluss', ['Lebensraum', 'Reichstag', 'Luftwaffe'], 'Anschluss, Avusturya\'nın Mart 1938\'de Nazi Almanyası\'na katılmasıdır. Lebensraum "yaşam alanı" anlamına gelen yayılmacı bir kavramdır.'),
  ('Birleşmiş Milletler Antlaşması 1945\'te hangi şehirde imzalanmıştır?', 'San Francisco', ['New York', 'Cenevre', 'Washington D.C.'], 'BM Antlaşması 26 Haziran 1945\'te San Francisco Konferansı\'nda imzalanmış ve 24 Ekim 1945\'te yürürlüğe girmiştir.'),
  ('BM Güvenlik Konseyi\'nin beş daimi üyesi arasında aşağıdakilerden hangisi yer almaz?', 'Almanya', ['Fransa', 'Çin', 'Birleşik Krallık'], 'Daimi üyeler ABD, Rusya (önce SSCB), Çin, Fransa ve Birleşik Krallık\'tır. Almanya II. Dünya Savaşı\'nın yenilen tarafı olduğundan daimi üye değildir.'),
  ('1948\'de BM Genel Kurulu\'nda kabul edilen ve temel hakları uluslararası düzeyde tanımlayan belge hangisidir?', 'İnsan Hakları Evrensel Beyannamesi', ['Avrupa İnsan Hakları Sözleşmesi ve Ek Protokolleri', 'Atlantik Bildirisi', 'Helsinki Nihai Senedi'], 'İnsan Hakları Evrensel Beyannamesi 10 Aralık 1948\'de Paris\'te kabul edilmiştir; bu nedenle 10 Aralık İnsan Hakları Günü olarak anılır.'),
  ('Winston Churchill\'in 1946\'da Fulton\'da yaptığı konuşmada Avrupa\'nın bölünmesini anlatmak için kullandığı ifade hangisidir?', 'Demir Perde', ['Soğuk Barış', 'Yeni Dünya Düzeni', 'Kızıl Tehlike'], 'Churchill "Baltık\'taki Stettin\'den Adriyatik\'teki Trieste\'ye kadar kıtanın üzerine bir demir perde inmiştir" diyerek Doğu ile Batı\'nın ayrılmasını anlatmıştır.'),
  ('1947\'de ilan edilen Marshall Planı\'nın temel amacı neydi?', 'Savaştan yıkılmış Avrupa\'yı ekonomik olarak kalkındırmak', ['Sovyetler Birliği\'ne askerî saldırı düzenlemek', 'Avrupa\'daki bütün sömürgeleri derhâl bağımsız kılmak', 'ABD\'nin Avrupa\'dan tümüyle çekilmesini sağlamak'], 'Marshall Planı, Batı Avrupa\'nın ekonomik toparlanmasını sağlayarak komünizmin yayılmasını engellemeyi amaçlayan bir yardım programıdır.'),
  ('NATO\'ya karşı 1955\'te Sovyetler Birliği önderliğinde kurulan askerî ittifak hangisidir?', 'Varşova Paktı', ['COMECON', 'Kominform', 'SEATO'], 'Varşova Paktı, Batı Almanya\'nın NATO\'ya katılmasının ardından 1955\'te kurulmuştur. COMECON ise 1949\'da kurulan Doğu bloku ekonomik örgütüdür.'),
  ('Doğu Almanya yönetimi Berlin Duvarı\'nı hangi yıl inşa etmiştir?', '1961', ['1949', '1953', '1968'], 'Doğu\'dan Batı\'ya kaçışları durdurmak için Ağustos 1961\'de Berlin Duvarı inşa edilmiş, Kasım 1989\'da yıkılmıştır.'),
  ('1968\'de Çekoslovakya\'da Alexander Dubček önderliğinde yaşanan ve Varşova Paktı müdahalesiyle sona eren reform dönemi hangi adla anılır?', 'Prag Baharı', ['Kadife Devrim', 'Dayanışma Hareketi', 'Turuncu Devrim'], 'Prag Baharı "insan yüzlü sosyalizm" girişimiydi; Ağustos 1968\'de Varşova Paktı birliklerinin işgaliyle bastırılmıştır. Kadife Devrim ise 1989\'da gerçekleşmiştir.'),
  ('Kore Savaşı\'nın başlamasına yol açan gelişme aşağıdakilerden hangisidir?', 'Kuzey Kore\'nin 38. paraleli geçerek güneye saldırması', ['Japonya\'nın Kore\'yi yeniden işgal etmesi', 'ABD\'nin Kuzey Kore\'ye atom bombası atması ve işgale başlaması', 'Çin\'in Güney Kore\'ye savaş ilan etmesi'], 'Haziran 1950\'de Kuzey Kore\'nin Güney\'e saldırması üzerine BM Güvenlik Konseyi müdahale kararı almış; ABD öncülüğünde BM kuvvetleri savaşa girmiştir.'),
  ('1962 Küba Füze Krizi hangi gelişmeyle başlamıştır?', 'Sovyetlerin Küba\'ya nükleer füze yerleştirmesi', ['ABD\'nin Küba\'ya asker çıkarması ve başkenti ele geçirmesi', 'Küba\'nın ABD\'ye savaş ilan etmesi', 'Çin\'in Küba\'ya ordu göndermesi'], 'ABD keşif uçakları Küba\'da Sovyet füze rampaları tespit edince Kennedy deniz ablukası ilan etmiş ve dünya nükleer savaşın eşiğine gelmiştir.'),
  ('Küba\'da 1959\'da Batista rejimini deviren devrimin lideri kimdir?', 'Fidel Castro', ['Salvador Allende', 'Augusto Pinochet', 'Daniel Ortega'], 'Fidel Castro ve Che Guevara\'nın yer aldığı devrimci hareket 1959\'da Batista\'yı devirmiş; Küba kısa sürede Sovyetlere yaklaşmıştır.'),
  ('Hindistan\'ın bağımsızlık mücadelesinde şiddet içermeyen sivil itaatsizlik yöntemini benimseyen lider kimdir?', 'Mahatma Gandi', ['Muhammed Ali Cinnah', 'Jawaharlal Nehru ile Kongre Partisi yönetimi', 'Subhas Chandra Bose'], 'Gandi, Tuz Yürüyüşü gibi barışçı direniş eylemleriyle İngiliz yönetimine karşı geniş halk desteği sağlamıştır.'),
  ('Hindistan 1947\'de bağımsızlığını kazanırken bölünmüştür. Bu bölünmeyle ortaya çıkan iki devlet hangileridir?', 'Hindistan ve Pakistan', ['Hindistan ve Sri Lanka', 'Hindistan ve Nepal', 'Pakistan ile Bangladeş ve Myanmar'], 'Dinî temelde gerçekleşen bölünmeyle Hindistan ve Pakistan kurulmuş; büyük göç dalgaları ve çatışmalar yaşanmıştır. Bangladeş ise 1971\'de Pakistan\'dan ayrılmıştır.'),
  ('1955\'te Asya ve Afrika ülkelerini bir araya getiren ve Bağlantısızlar Hareketi\'nin öncüsü sayılan konferans hangisidir?', 'Bandung Konferansı', ['Belgrad Konferansı', 'Yalta Konferansı', 'Bretton Woods Konferansı'], 'Endonezya\'nın Bandung kentinde yapılan konferans sömürgeciliğe karşı dayanışmayı vurgulamış; Bağlantısızlar Hareketi 1961\'de Belgrad\'da resmen kurulmuştur.'),
  ('Bağlantısızlar Hareketi\'ne katılan ülkelerin temel dış politika tercihi neydi?', 'İki süper güç blokuna da bağlanmamak', ['NATO\'ya toplu olarak üye olmak', 'Varşova Paktı\'na askerî destek vermek', 'Sömürgeci devletlerle ortak ordu kurmak ve üs vermek'], 'Bağlantısızlar, Soğuk Savaş\'ta ABD ya da SSCB liderliğindeki bloklardan birine katılmadan bağımsız bir politika izlemeyi amaçlamıştır.'),
  ('Güney Afrika\'da uygulanan ırk ayrımcılığı politikasının adı ve bu sisteme karşı mücadelenin simgesi olan lider hangisidir?', 'Apartheid; Nelson Mandela', ['Segregasyon; Martin Luther King', 'Kast sistemi; Mahatma Gandi', 'Kolonyalizm; Kwame Nkrumah'], 'Apartheid 1948\'de resmî politika olmuş; 27 yıl hapis yatan Nelson Mandela 1994\'te ülkenin ilk siyahi devlet başkanı seçilmiştir.'),
  ('Endonezya hangi devletin sömürgesiyken bağımsızlığını ilan etmiştir?', 'Hollanda', ['İngiltere', 'Fransa', 'Portekiz'], 'Endonezya 1945\'te Sukarno önderliğinde bağımsızlığını ilan etmiş, Hollanda 1949\'da bu bağımsızlığı tanımıştır.'),
  ('İsrail Devleti hangi yıl kurulmuştur?', '1948', ['1945', '1956', '1967'], 'İngiliz mandasının sona ermesiyle İsrail 14 Mayıs 1948\'de kurulmuş; hemen ardından ilk Arap-İsrail Savaşı başlamıştır.'),
  ('1978\'de ABD arabuluculuğunda Mısır ile İsrail arasında imzalanan barış çerçevesi hangisidir?', 'Camp David Anlaşmaları', ['Oslo Anlaşmaları', 'Dayton Anlaşması', 'Taif Anlaşması'], 'Enver Sedat ile Menahem Begin, Başkan Carter\'ın arabuluculuğuyla Camp David\'de anlaşmış; Mısır 1979 antlaşmasıyla İsrail\'i tanıyan ilk Arap ülkesi olmuştur.'),
  ('1980-1988 yılları arasında süren ve Orta Doğu\'nun en uzun konvansiyonel savaşlarından biri olan çatışma hangisidir?', 'İran-Irak Savaşı', ['Körfez Savaşı', 'Altı Gün Savaşı', 'Lübnan İç Savaşı ve İsrail müdahalesi'], 'Saddam Hüseyin\'in 1980\'de İran\'a saldırmasıyla başlayan savaş, 1988\'de BM ateşkesiyle sona ermiş ve iki taraf da büyük kayıplar vermiştir.'),
  ('1990\'da Irak\'ın Kuveyt\'i işgal etmesinin ardından 1991\'de ABD öncülüğündeki koalisyonun başlattığı harekât hangisidir?', 'Çöl Fırtınası', ['Irak\'ı Özgürleştirme', 'Kararlı Destek', 'Kesintisiz Özgürlük'], 'Çöl Fırtınası Harekâtı ile Irak ordusu Kuveyt\'ten çıkarılmıştır. Irak\'ı Özgürleştirme ise 2003 Irak işgalinin adıdır.'),
  ('1949\'da Çin Halk Cumhuriyeti\'ni ilan eden lider kimdir?', 'Mao Zedong', ['Çan Kay-şek', 'Deng Xiaoping', 'Sun Yat-sen'], 'Mao Zedong önderliğindeki komünistler iç savaşı kazanarak 1 Ekim 1949\'da Çin Halk Cumhuriyeti\'ni ilan etmiştir.'),
  ('Çin İç Savaşı\'nı kaybeden Milliyetçi Çan Kay-şek yönetimi 1949\'da nereye çekilmiştir?', 'Tayvan', ['Hong Kong', 'Mançurya', 'Tibet'], 'Kuomintang hükümeti Tayvan Adası\'na çekilmiş ve burada Çin Cumhuriyeti\'ni sürdürmüştür.'),
  ('Çin\'de 1966-1976 arasında Kızıl Muhafızların "burjuva" ve geleneksel unsurlara karşı yürüttüğü hareket hangi adla bilinir?', 'Kültür Devrimi', ['Uzun Yürüyüş', 'Boxer Ayaklanması', 'Tiananmen Olayları ve sonrası'], 'Mao\'nun başlattığı Kültür Devrimi\'nde aydınlar, yöneticiler ve kültürel miras hedef alınmış; ülke büyük bir kaosa sürüklenmiştir.'),
  ('Mao\'nun ölümünden sonra Çin\'de piyasa ekonomisine yönelik reformları başlatan lider kimdir?', 'Deng Xiaoping', ['Zhou Enlai', 'Lin Biao', 'Hua Guofeng ve Dörtlü Çete'], 'Deng Xiaoping 1978\'den itibaren "reform ve dışa açılım" politikasıyla özel girişime ve yabancı yatırıma kapı açmış, Çin\'in hızlı büyümesini başlatmıştır.'),
  ('Avrupa Ekonomik Topluluğu\'nu kuran antlaşma hangisidir?', 'Roma Antlaşması (1957)', ['Maastricht Antlaşması (1992)', 'Lizbon Antlaşması (2007)', 'Paris Antlaşması (1951)'], '25 Mart 1957\'de imzalanan Roma Antlaşması ile Avrupa Ekonomik Topluluğu ve Avrupa Atom Enerjisi Topluluğu kurulmuştur.'),
  ('Sovyetler Birliği\'nde 1985\'te iktidara gelen ve "glasnost" ile "perestroyka" politikalarını uygulayan lider kimdir?', 'Mihail Gorbaçov', ['Leonid Brejnev', 'Boris Yeltsin', 'Yuri Andropov'], 'Gorbaçov, glasnost (açıklık) ve perestroyka (yeniden yapılanma) ile Sovyet sistemini reform etmeye çalışmış; bu süreç birliğin dağılmasına giden yolu açmıştır.'),
  ('Berlin Duvarı hangi tarihte yıkılmıştır?', '9 Kasım 1989', ['3 Ekim 1990', '25 Aralık 1991', '13 Ağustos 1961'], 'Berlin Duvarı 9 Kasım 1989\'da açılmıştır. 3 Ekim 1990 Almanya\'nın birleşme tarihi, 25 Aralık 1991 SSCB\'nin dağılma tarihi, 13 Ağustos 1961 duvarın inşasının başladığı tarihtir.'),
  ('1970\'lerde ABD ile SSCB arasındaki gerginliğin azaldığı ve SALT görüşmelerinin yapıldığı dönem hangi adla bilinir?', 'Yumuşama', ['Çevreleme dönemi', 'Yatıştırma dönemi', 'Büyük Buhran dönemi'], 'Détente döneminde stratejik silahların sınırlandırılması (SALT I, 1972) ve 1975 Helsinki Nihai Senedi gibi adımlar atılmıştır.'),
  ('Sovyetler Birliği\'nin 1979\'da müdahale ettiği ve on yıl süren savaşla sonuçlanan ülke hangisidir?', 'Afganistan', ['Polonya', 'İran', 'Çekoslovakya'], 'SSCB Aralık 1979\'da Afganistan\'a girmiş, mücahitlere karşı uzun ve maliyetli bir savaştan sonra 1989\'da çekilmiştir. Bu müdahale yumuşama döneminin sonu sayılır.'),
  ('Yugoslavya\'nın 1990\'larda dağılma sürecinde yaşanan Bosna Savaşı\'nı sona erdiren antlaşma hangisidir?', 'Dayton Antlaşması', ['Oslo Anlaşmaları', 'Helsinki Nihai Senedi', 'Camp David Anlaşmaları'], '1995\'te ABD\'nin Dayton kentinde imzalanan antlaşma ile Bosna Savaşı sona ermiş ve Bosna-Hersek iki entiteli bir yapıya kavuşmuştur.'),
  ('Bosna Savaşı sırasında 1995\'te binlerce Boşnak erkeğin Sırp güçlerince öldürüldüğü ve uluslararası mahkemelerce soykırım olarak nitelendirilen katliam nerede yaşanmıştır?', 'Srebrenitsa', ['Saraybosna', 'Mostar', 'Tuzla'], 'Temmuz 1995\'te BM güvenli bölgesi ilan edilmiş Srebrenitsa\'da yaklaşık 8.000 Boşnak öldürülmüştür; Lahey\'deki mahkemeler bunu soykırım olarak tanımlamıştır.'),
  ('Dünyanın ilk yapay uydusu olan Sputnik 1 hangi ülke tarafından ve hangi yıl fırlatılmıştır?', 'Sovyetler Birliği, 1957', ['ABD, 1958', 'Sovyetler Birliği, 1961', 'ABD, 1955'], 'Sputnik 1\'in 4 Ekim 1957\'de fırlatılması ABD\'de "Sputnik şoku" yaratmış ve uzay yarışını başlatmıştır.'),
  ('Sputnik şokunun ardından ABD\'nin 1958\'de kurduğu kurum hangisidir?', 'NASA', ['CIA', 'NATO', 'FBI'], 'Ulusal Havacılık ve Uzay Dairesi (NASA) 1958\'de kurularak ABD\'nin sivil uzay programını yürütmeye başlamıştır.'),
  ('Ay\'a ilk insanlı inişi gerçekleştiren görev ve yılı hangisidir?', 'Apollo 11, 1969', ['Apollo 13, 1970', 'Gemini 4, 1965', 'Apollo 8, 1968'], 'Neil Armstrong ve Buzz Aldrin 20 Temmuz 1969\'da Apollo 11 göreviyle Ay\'a inmiştir. Apollo 8 Ay\'ın çevresinde dönmüş, Apollo 13 ise arıza nedeniyle inememiştir.'),
  ('1986\'da Ukrayna\'da meydana gelen ve tarihin en büyük nükleer kazalarından biri olan felaket hangisidir?', 'Çernobil', ['Fukuşima', 'Three Mile Island', 'Kıştım'], '26 Nisan 1986\'da Çernobil Nükleer Santrali\'nin 4. reaktöründe patlama olmuş; radyoaktif bulut Avrupa\'ya yayılmıştır. Fukuşima 2011\'de Japonya\'da yaşanmıştır.'),
  ('20. yüzyılda Alexander Fleming\'in 1928\'de keşfettiği ve II. Dünya Savaşı\'nda yaygınlaşan ilaç hangisidir?', 'Penisilin', ['Aspirin', 'İnsülin', 'Morfin'], 'Fleming küf mantarından elde edilen penisilinin bakterileri öldürdüğünü bulmuş; ilaç II. Dünya Savaşı sırasında seri üretilerek pek çok yaralının hayatını kurtarmıştır.'),
  ('II. Dünya Savaşı sırasında ABD\'nin atom bombası geliştirmek için yürüttüğü gizli program hangisidir?', 'Manhattan Projesi', ['Apollo Programı', 'Yıldız Savaşları Girişimi', 'Marshall Planı'], 'Robert Oppenheimer\'ın bilimsel yönetimindeki Manhattan Projesi ilk atom bombalarını üretmiş; ilk deneme Temmuz 1945\'te New Mexico\'da yapılmıştır.'),
  ('Kuvâ-yı Milliye birliklerinin temel özelliklerinden biri aşağıdakilerden hangisidir?', 'Gönüllülük esasına dayanması', ['Merkezî bir komuta altında disiplinli çalışması', 'İstanbul hükümetince maaşla desteklenmesi', 'Yabancı subaylar tarafından eğitilmesi ve yönetilmesi'], 'Kuvâ-yı Milliye halkın gönüllü katılımıyla oluşmuş, bölgesel ve dağınık yapıda olup düzenli bir ordu disiplinine sahip değildi.'),
  ('Millî Mücadele\'yi yurt içinde ve dışında duyurmak amacıyla 6 Nisan 1920\'de kurulan haber kuruluşu hangisidir?', 'Anadolu Ajansı', ['Türkiye Radyo ve Televizyon Kurumu', 'Cihan Haber Ajansı', 'Basın Yayın Genel Müdürlüğü ve Matbuat Cemiyeti'], 'Anadolu Ajansı, TBMM\'nin açılışından kısa süre önce Halide Edib ve Yunus Nadi\'nin önerisiyle kurulmuş ve ilk haberi TBMM\'nin açılacağıdır.'),
  ('Sakarya Meydan Muharebesi\'nin kaç gün kaç gece sürdüğü kabul edilir?', '22 gün 22 gece', ['7 gün 7 gece', '14 gün 14 gece', '40 gün 40 gece'], '23 Ağustos-13 Eylül 1921 tarihleri arasında yapılan Sakarya Meydan Muharebesi 22 gün 22 gece sürmüştür.'),
  ('Millî Mücadele\'de kadınların ön plana çıkan katkıları arasında aşağıdakilerden hangisi yer alır?', 'Cepheye kağnılarla cephane taşımaları', ['TBMM\'de milletvekili olarak görev yapmaları', 'İstanbul hükümetinde bakan olmaları', 'Lozan\'da Türk heyetini yönetmeleri'], 'Şerife Bacı gibi Anadolu kadınları cepheye cephane taşımış, Kara Fatma ve Halide Edib gibi isimler cephede görev almıştır; kadınlar ise siyasi haklarını 1930\'lardan sonra kazanmıştır.'),
  ('Mustafa Kemal\'in Millî Mücadele\'yi başlatmak için 19 Mayıs 1919\'da Samsun\'a çıkışı bugün hangi bayramla anılmaktadır?', 'Atatürk\'ü Anma, Gençlik ve Spor Bayramı', ['Ulusal Egemenlik ve Çocuk Bayramı', 'Zafer Bayramı ve Türk Silahlı Kuvvetleri Günü', 'Cumhuriyet Bayramı'], '19 Mayıs, Atatürk\'ün gençliğe armağan ettiği bir gün olarak Atatürk\'ü Anma, Gençlik ve Spor Bayramı şeklinde kutlanır.'),
  ('Mustafa Kemal\'in "Ya istiklal ya ölüm!" sözü Millî Mücadele\'nin hangi temel ilkesini en açık biçimde yansıtır?', 'Tam bağımsızlık', ['Devletçilik', 'Halkçılık', 'Laiklik'], 'Bu söz, bağımsızlığın ödün verilmeden elde edileceğini ve gerekirse bu uğurda ölmeyi göze alındığını ifade eder.'),
  ('Lozan Antlaşması hangi tarihte imzalanmıştır?', '24 Temmuz 1923', ['20 Kasım 1922', '29 Ekim 1923', '3 Mart 1924'], 'Konferans 20 Kasım 1922\'de başlamış, antlaşma 24 Temmuz 1923\'te imzalanmıştır. İtilaf kuvvetleri İstanbul\'u Ekim 1923\'te boşaltmıştır.'),
  ('Türkiye\'nin 1932\'de Milletler Cemiyeti\'ne üye olması hangi dış politika anlayışıyla uyumludur?', 'Uluslararası barışa ve iş birliğine katkı', ['Bloklardan tümüyle uzak durma ve yalnızlık', 'Yeni topraklar kazanma hedefi', 'Sömürge edinme isteği'], 'Türkiye, Milletler Cemiyeti üyeliğiyle barışçı ve uluslararası hukuka saygılı dış politikasını kurumsal bir zemine taşımıştır.'),
  ('Demokrat Parti döneminde 1955\'te İstanbul\'da azınlıklara yönelik yağma ve saldırılarla sonuçlanan olaylar hangi adla anılır?', '6-7 Eylül Olayları', ['31 Mart Vakası', 'Menemen Olayı', '27 Mayıs Olayları'], 'Selanik\'teki Atatürk\'ün doğduğu eve bomba atıldığı yönündeki asılsız haberle başlayan 6-7 Eylül 1955 olaylarında Rum, Ermeni ve Yahudi vatandaşların mülkleri tahrip edilmiştir.'),
  ('1960 müdahalesinden sonra 1961\'de cumhurbaşkanı seçilen kişi kimdir?', 'Cemal Gürsel', ['Cevdet Sunay', 'Fahri Korutürk', 'Celal Bayar'], 'Millî Birlik Komitesi başkanı Cemal Gürsel, 1961 seçimlerinin ardından TBMM tarafından cumhurbaşkanı seçilmiştir.'),
  ('Kıbrıs Barış Harekâtı hangi tarihte başlamıştır?', '20 Temmuz 1974', ['15 Kasım 1983', '16 Ağustos 1960', '21 Aralık 1963'], 'Harekât 20 Temmuz 1974\'te başlamış, ikinci aşaması Ağustos 1974\'te gerçekleştirilmiştir. 15 Kasım 1983 KKTC\'nin ilanıdır.'),
  ('I. Dünya Savaşı öncesinde Almanya, Avusturya-Macaristan ve İtalya\'nın oluşturduğu blok hangi adla bilinir?', 'Üçlü İttifak', ['Üçlü İtilaf', 'Kutsal İttifak', 'Mihver Devletleri ve Anti-Komintern Bloğu'], '1882\'de kurulan Üçlü İttifak\'a karşı İngiltere, Fransa ve Rusya Üçlü İtilaf\'ı oluşturmuştur. İtalya savaş başlayınca tarafsız kalmış, 1915\'te İtilaf safına geçmiştir.'),
  ('Stalin\'in ölümünden sonra 1956\'da yaptığı "gizli konuşmayla" Stalin dönemini eleştiren Sovyet lider kimdir?', 'Nikita Kruşçev', ['Leonid Brejnev', 'Mihail Gorbaçov', 'Georgi Malenkov ve Beria'], 'Kruşçev, 1956\'daki 20. Parti Kongresi\'nde Stalin\'in kişi kültünü ve baskılarını eleştirmiş; bu süreç destalinizasyon olarak anılır.'),
  ('Almanya\'da I. Dünya Savaşı\'ndan sonra kurulan ve Hitler\'in iktidara gelmesiyle sona eren demokratik rejim hangisidir?', 'Weimar Cumhuriyeti', ['Üçüncü Reich', 'Bonn Cumhuriyeti', 'Prusya Krallığı'], '1919\'da kurulan Weimar Cumhuriyeti, ekonomik krizler ve siyasi istikrarsızlık içinde zayıflamış ve 1933\'te Nazi yönetimine geçilmiştir.'),
  ('Pasifik\'te 1942\'de ABD donanmasının Japon uçak gemilerini batırarak savaşın dengesini değiştirdiği muharebe hangisidir?', 'Midway', ['Pearl Harbor', 'Okinawa', 'Iwo Jima'], 'Haziran 1942\'deki Midway Muharebesi\'nde Japonya dört uçak gemisini kaybetmiş; bu tarihten sonra Pasifik\'te inisiyatif ABD\'ye geçmiştir.'),
  ('Almanya\'nın II. Dünya Savaşı\'nda koşulsuz teslim olduğu ay ve yıl hangisidir?', 'Mayıs 1945', ['Ağustos 1945', 'Haziran 1944', 'Nisan 1946'], 'Almanya 7-8 Mayıs 1945\'te koşulsuz teslim olmuş; Avrupa\'da savaş sona ermiştir. Japonya ise Ağustos-Eylül 1945\'te teslim olmuştur.'),
  ('II. Dünya Savaşı\'nda Fransa\'nın Almanlarca işgalinin ardından Londra\'dan "Özgür Fransa" hareketini yöneten lider kimdir?', 'Charles de Gaulle', ['Philippe Pétain', 'Georges Clemenceau', 'Léon Blum ve Halk Cephesi'], 'De Gaulle Haziran 1940\'ta Londra\'dan direniş çağrısı yapmıştır. Mareşal Pétain ise Almanlarla iş birliği yapan Vichy rejiminin başındaydı.'),
  ('II. Dünya Savaşı\'nda Fransa\'nın Almanlar tarafından işgal edilmeyen güney kesiminde kurulan iş birlikçi yönetim hangi şehrin adıyla anılır?', 'Vichy', ['Lyon', 'Marsilya', 'Bordeaux'], 'Mareşal Pétain\'in başındaki Vichy rejimi, Almanya ile ateşkesin ardından 1940\'ta kurulmuş ve Almanlarla iş birliği yapmıştır.'),
  ('II. Dünya Savaşı sırasında Almanya\'nın yaklaşık 900 gün kuşattığı ancak ele geçiremediği Sovyet şehri hangisidir?', 'Leningrad', ['Moskova', 'Kiev', 'Odessa'], 'Leningrad (bugünkü St. Petersburg) Eylül 1941\'den Ocak 1944\'e kadar kuşatılmış, açlık nedeniyle yüz binlerce sivil hayatını kaybetmiştir.'),
  ('1989\'da Kenan Evren\'in ardından TBMM tarafından cumhurbaşkanı seçilen başbakan kimdir?', 'Turgut Özal', ['Süleyman Demirel', 'Bülent Ulusu', 'Necmettin Erbakan ve Refah Partisi'], 'Turgut Özal 31 Ekim 1989\'da cumhurbaşkanı seçilmiş ve 1993\'teki ölümüne kadar bu görevde kalmıştır.'),
  ('Bir tarih öğretmeni "Bu ilke, inkılapların korunmasını sağlarken aynı zamanda değişime açık olmayı gerektirir; bu nedenle Atatürk ilkelerinin dinamik yapısını gösterir" diyor. Öğretmen hangi ilkeyi anlatmaktadır?', 'İnkılapçılık', ['Milliyetçilik', 'Devletçilik', 'Halkçılık'], 'İnkılapçılık, yapılan yenilikleri korumayı ve toplumu sürekli çağdaşlaştırmayı öngördüğü için Atatürk ilkelerinin dinamizmini sağlar.'),
  ('Atatürk\'ün "Hayatta en hakiki mürşit ilimdir" sözü hangi inkılap alanının temel anlayışını en iyi yansıtır?', 'Eğitimde bilimsellik ve akılcılık', ['Ekonomide devletin rolü', 'Dış politikada barışçılık', 'Siyasette çok partili yaşam ve muhalefet'], 'Bu söz bilimi hayatın yol göstericisi sayar; eğitim inkılapları ve laik eğitim anlayışı bu düşünceye dayanır.'),
  ('Atatürk\'ün Cumhuriyet\'in 10. yılında okuduğu nutukta yer alan "Muasır medeniyet seviyesinin üstüne çıkmak" hedefi aşağıdakilerden hangisini ifade eder?', 'Çağdaş uygarlık düzeyini aşmayı', ['Osmanlı sınırlarına geri dönmeyi', 'Batı\'dan tümüyle kopmayı ve yalnızlığı', 'Yalnız askerî güç kazanmayı'], 'Onuncu Yıl Nutku\'nda Atatürk, Türk milletinin çağdaş uygarlık seviyesine ulaşmakla yetinmeyip onun da üstüne çıkmasını hedef olarak göstermiştir.'),
  ('Atatürk\'ün ölümüne kadar kesintisiz yaptığı görev hangisidir?', 'Cumhurbaşkanlığı', ['Başbakanlık', 'Genelkurmay Başkanlığı', 'TBMM Başkanlığı ve İcra Vekilleri Heyeti Başkanlığı'], 'Atatürk 29 Ekim 1923\'ten 10 Kasım 1938\'e kadar dört kez cumhurbaşkanı seçilmiş ve bu görevi ölümüne kadar sürdürmüştür.'),
  ('Atatürk\'ün "Benim naçiz vücudum elbet bir gün toprak olacaktır, fakat Türkiye Cumhuriyeti ilelebet payidar kalacaktır" sözü hangi düşünceyi vurgular?', 'Cumhuriyetin kişilerden bağımsız olarak sürekliliğini', ['Cumhuriyetin yalnız Atatürk\'e bağlı olduğunu', 'Saltanatın geri dönebileceğini', 'Devletin ömrünün sınırlı olduğunu ve yıkılacağını'], 'Atatürk bu sözle kurduğu rejimin kendi ömrüyle sınırlı olmadığını ve Türk milletinin cumhuriyeti sonsuza kadar yaşatacağını vurgulamıştır.'),
  ('1952\'de Mısır\'da monarşiyi deviren Hür Subaylar hareketinin ardından Arap milliyetçiliğinin simgesi hâline gelen lider kimdir?', 'Cemal Abdünnasır', ['Enver Sedat', 'Hüsnü Mübarek', 'Kral Faruk ve Vafd Partisi'], '1952 darbesinden sonra Nasır 1954\'te yönetimi tümüyle ele geçirmiş; Süveyş\'i millîleştirmesi ve Arap birliği söylemiyle bölgenin en etkili liderlerinden biri olmuştur.'),
  ('Filistin Kurtuluş Örgütü\'nün (FKÖ) uzun yıllar lideri olan ve 1994 Nobel Barış Ödülü\'nü İsrailli liderlerle paylaşan kişi kimdir?', 'Yaser Arafat', ['Mahmud Abbas', 'Ahmed Yasin', 'Cemal Abdünnasır ve Enver Sedat'], 'Arafat, Oslo süreci nedeniyle Yitzhak Rabin ve Şimon Peres ile birlikte 1994 Nobel Barış Ödülü\'nü almıştır.'),
  ('1945\'te Ho Chi Minh tarafından bağımsızlığı ilan edilen ülke hangisidir?', 'Vietnam', ['Kamboçya', 'Laos', 'Tayland'], 'Ho Chi Minh, Japonların teslim olmasının ardından Eylül 1945\'te Hanoi\'de Vietnam Demokratik Cumhuriyeti\'nin bağımsızlığını ilan etmiştir.'),
  ('Martin Luther King\'in "Bir hayalim var" konuşmasını yaptığı 1963 olayı hangi hareketle ilişkilidir?', 'ABD\'deki sivil haklar hareketi', ['Güney Afrika\'daki apartheid karşıtı hareket', 'Hindistan\'daki bağımsızlık hareketi', 'Avrupa\'daki öğrenci hareketleri ve 1968 olayları'], 'King, 28 Ağustos 1963\'teki Washington Yürüyüşü\'nde siyahilerin eşit haklar talebini dile getiren ünlü konuşmasını yapmıştır; 1964\'te Sivil Haklar Yasası çıkarılmıştır.'),
  ('ABD Başkanı John F. Kennedy hangi yıl ve hangi şehirde suikastla öldürülmüştür?', '1963, Dallas', ['1968, Memphis', '1961, Washington', '1965, New York'], 'Kennedy 22 Kasım 1963\'te Dallas\'ta suikasta kurban gitmiştir. Martin Luther King ise 1968\'de Memphis\'te öldürülmüştür.'),
  ('1974\'te ABD\'de Başkan Nixon\'ın istifasına yol açan skandal hangisidir?', 'Watergate', ['İran-Kontra', 'Pentagon Belgeleri', 'Teapot Dome'], 'Demokrat Parti merkezine yapılan dinleme girişimi ve Nixon yönetiminin bunu örtbas etmeye çalışması ortaya çıkınca Nixon Ağustos 1974\'te istifa etmiştir.'),
  ('Almanya\'nın yeniden birleşmesi hangi tarihte gerçekleşmiştir?', '3 Ekim 1990', ['9 Kasım 1989', '1 Ocak 1993', '25 Aralık 1991'], 'Doğu Almanya 3 Ekim 1990\'da Federal Almanya\'ya katılmış ve Almanya yeniden birleşmiştir.'),
  ('Çekoslovakya\'da 1989\'da komünist yönetimin barışçı yollarla sona ermesi hangi adla anılır?', 'Kadife Devrim', ['Prag Baharı', 'Gül Devrimi', 'Dayanışma Hareketi ve grevler'], 'Kasım 1989\'daki Kadife Devrim\'le komünist yönetim kansız biçimde çekilmiş, Václav Havel cumhurbaşkanı olmuştur. Çekoslovakya 1993\'te Çek Cumhuriyeti ve Slovakya olarak ikiye ayrılmıştır.'),
  ('Yugoslavya\'yı II. Dünya Savaşı\'ndan sonra 1980\'deki ölümüne kadar yöneten ve Sovyetlerden bağımsız bir sosyalist çizgi izleyen lider kimdir?', 'Josip Broz Tito', ['Slobodan Miloşeviç', 'Alija İzetbegoviç', 'Enver Hoca'], 'Tito, 1948\'de Stalin ile yollarını ayırmış, Bağlantısızlar Hareketi\'nin kurucuları arasında yer almıştır. Ölümünden sonra Yugoslavya\'daki gerilimler artmıştır.'),
  ('Harf İnkılabı\'nın Türk toplumuna en önemli etkilerinden biri aşağıdakilerden hangisidir?', 'Okuma yazma oranının artması', ['Osmanlıca eserlerin tümüyle yok edilmesi', 'Yabancı dil öğreniminin yasaklanması', 'Matbaanın Türkiye\'ye ilk kez gelmesi ve kitap basımı'], 'Latin harflerinin Türkçenin ses yapısına daha uygun olması okuma yazmayı kolaylaştırmış; Millet Mektepleri ile birlikte okuryazarlık hızla yükselmiştir.'),
  ('Cumhuriyetin ilk yıllarında Türkiye\'de sağlık alanında yapılan çalışmalar arasında aşağıdakilerden hangisi yer alır?', 'Sıtma ve verem gibi salgın hastalıklarla mücadele edilmesi', ['Bütün hastanelerin yabancı şirketlere devredilmesi', 'Tıp fakültelerinin kapatılması ve hekimliğin yasaklanması', 'Aşı uygulamalarının durdurulması'], 'Sağlık ve Sosyal Yardım Vekâleti\'nin kurulması, Refik Saydam\'ın çalışmaları ve Hıfzıssıhha Enstitüsü ile salgın hastalıklara karşı yaygın bir mücadele yürütülmüştür.'),
  ('Hindistan\'ın bağımsızlığından sonra ilk başbakanı olan lider kimdir?', 'Jawaharlal Nehru', ['Mahatma Gandi', 'Indira Gandhi', 'Muhammed Ali Cinnah'], 'Nehru 1947\'den 1964\'teki ölümüne kadar başbakanlık yapmış ve Bağlantısızlar Hareketi\'nin öncüleri arasında yer almıştır. Cinnah ise Pakistan\'ın kurucusudur.'),
  ('1971\'de Doğu Pakistan\'ın ayrılmasıyla kurulan devlet hangisidir?', 'Bangladeş', ['Sri Lanka', 'Myanmar', 'Nepal'], 'Doğu Pakistan, Hindistan\'ın da müdahale ettiği savaşın ardından 1971\'de Bangladeş adıyla bağımsızlığını kazanmıştır.'),
  ('Çin\'de 1989\'da Pekin\'deki bir meydanda demokrasi talep eden öğrenci gösterilerinin askerî güçle bastırılması hangi adla anılır?', 'Tiananmen Meydanı olayları', ['Kültür Devrimi', 'Yüz Çiçek Kampanyası', 'Boxer Ayaklanması ve Yabancı Elçilikler'], 'Haziran 1989\'da Tiananmen Meydanı\'ndaki gösteriler ordu tarafından bastırılmış; olay Çin\'in siyasi reformlara kapalı tutumunun simgesi olmuştur.'),
  ('Birleşik Krallık\'ın Hong Kong\'u Çin\'e devrettiği yıl hangisidir?', '1997', ['1984', '1999', '1949'], 'Hong Kong 1 Temmuz 1997\'de "tek ülke, iki sistem" ilkesiyle Çin\'e devredilmiştir. 1984 devri öngören ortak bildirinin, 1999 ise Makao\'nun devrinin yılıdır.'),
  ('Avrupa\'da II. Dünya Savaşı\'ndaki Müttefik kuvvetlerin başkomutanı olan ve sonradan ABD başkanı seçilen kişi kimdir?', 'Dwight D. Eisenhower', ['Harry Truman', 'Douglas MacArthur', 'George Marshall'], 'Eisenhower, Normandiya çıkarmasını yöneten Müttefik başkomutanıdır; 1953-1961 arasında ABD başkanlığı yapmıştır.'),
  ('1985\'te imzalanan ve Avrupa\'da üye ülkeler arasında sınır kontrollerinin kaldırılmasını öngören anlaşma hangisidir?', 'Schengen Anlaşması', ['Maastricht Antlaşması', 'Roma Antlaşması', 'Lizbon Antlaşması'], 'Lüksemburg\'un Schengen köyünde imzalanan anlaşma, iç sınırlarda pasaport kontrolünün kaldırılmasını öngörmüş ve 1995\'te uygulanmaya başlamıştır.'),
  ('1957\'de fırlatılan Sputnik 2 ile uzaya gönderilen ilk canlı hangisidir?', 'Köpek Layka', ['Şempanze Ham', 'Köpekler Belka ve Strelka', 'Maymun Albert II'], 'Sovyetler Kasım 1957\'de Sputnik 2 ile köpek Layka\'yı yörüngeye göndermiştir. Belka ile Strelka 1960\'ta uzaydan sağ dönen köpeklerdir.'),
  ('Atatürk\'ün 1919-1922 arasındaki kararlarından hangisi askerî değil siyasi-diplomatik bir nitelik taşır?', 'Londra Konferansı\'na TBMM heyeti göndermesi', ['Sakarya\'nın doğusuna çekilme kararı', 'Büyük Taarruz\'u Kocatepe\'den başlatması', 'Kuvâ-yı Milliye\'yi düzenli orduya dönüştürmesi'], 'Londra Konferansı\'na katılım diplomatik bir adımdır; diğer kararlar doğrudan askerî stratejiyle ilgilidir.'),
  ('1921, 1924, 1961 ve 1982 anayasaları karşılaştırıldığında hangisinin yalnızca olağanüstü savaş koşullarında hazırlanmış bir anayasa olduğu söylenebilir?', '1921 Anayasası', ['1924 Anayasası', '1961 Anayasası', '1982 Anayasası'], '1921 Teşkilât-ı Esasiye Kanunu Millî Mücadele sürerken hazırlanmış kısa bir anayasadır; diğerleri barış döneminde hazırlanmıştır.'),
  ('Bir siyaset bilimci "Bu seçim, Türkiye\'de iktidarın ilk kez seçimle ve barışçı yolla el değiştirdiği seçimdir" diyor. Söz konusu seçim hangisidir?', '1950 genel seçimi', ['1946 genel seçimi', '1935 genel seçimi', '1961 genel seçimi'], '14 Mayıs 1950 seçimlerinde CHP iktidarı DP\'ye devretmiştir; 1946 seçimlerini ise CHP kazanmıştır.'),
  ('Bir ülke, Soğuk Savaş döneminde ne NATO\'ya ne de Varşova Paktı\'na katılmış; sömürgecilikten yeni kurtulmuş ülkelerle iş birliği yapmıştır. Bu ülkenin dış politikası hangi harekete uygundur?', 'Bağlantısızlar Hareketi', ['Avrupa Birliği', 'Atlantik İttifakı', 'Kominform'], 'Blokların dışında kalıp Asya, Afrika ve Latin Amerika ülkeleriyle dayanışmayı seçen ülkeler Bağlantısızlar Hareketi\'nde yer almıştır.'),
  ('Berlin Duvarı\'nın yapılması ve yıkılması arasında geçen süre yaklaşık kaç yıldır?', '28', ['18', '32', '44'], 'Duvar 1961\'de inşa edilip 1989\'da yıkılmıştır; 1989 - 1961 = 28 yıl eder.'),
  ('Bir öğrenci 1919\'da yazılmış bir mektupta "Erzurum\'da alınan kararların bütün yurdu kapsadığını, ancak delegelerin yalnız doğu illerinden geldiğini" okuyor. Bu mektup hangi konuyu doğru biçimde açıklamaktadır?', 'Erzurum Kongresi\'nin toplanış bakımından bölgesel, kararlar bakımından ulusal olduğunu', ['Sivas Kongresi\'nin bütün illerden temsilci almadığını', 'Amasya Genelgesi\'nin yalnız doğu illerine gönderildiğini', 'Misak-ı Millî\'nin Erzurum\'da kabul edildiğini ve ilan edildiğini'], 'Erzurum Kongresi\'ne yalnız doğu illerinden delege katılmış, ancak kararlar bütün vatanı ilgilendirdiğinden ulusal nitelik taşımıştır.'),
  ('Bir gazetede 1926\'da yayımlanan haberde "Bundan böyle evlenmeler belediye memuru önünde yapılacak, birden fazla eşle evlenmek yasaklanacaktır" deniyor. Haber hangi düzenlemeyle ilgilidir?', 'Türk Medeni Kanunu', ['Türk Ceza Kanunu', 'Tevhid-i Tedrisat Kanunu', 'Soyadı Kanunu'], 'Medeni Kanun resmî nikâhı zorunlu kılmış ve tek eşliliği esas almıştır.'),
  ('Bir yabancı gezgin 1936\'da Türkiye\'de pazar günü dükkânların kapalı olduğunu, saatin uluslararası sisteme göre ayarlandığını ve tartının kilogramla yapıldığını yazıyor. Gezginin gözlemleri hangi alandaki inkılapların sonucudur?', 'Toplumsal hayatın düzenlenmesi', ['Hukuk sisteminin değişmesi', 'Dış politikanın yeniden yapılanması', 'Siyasi rejimin değişmesi'], 'Hafta tatili, uluslararası saat ve ölçüler kanunları toplumsal hayatı ve ticareti dünya ile uyumlu hâle getirmek için yapılan düzenlemelerdir.'),
  ('Aşağıdaki gelişmelerden hangisi II. Dünya Savaşı\'nın sonuçlarından biri değildir?', 'Milletler Cemiyeti\'nin kurulması', ['Birleşmiş Milletler\'in kurulması', 'Almanya\'nın işgal bölgelerine ayrılması', 'ABD ile SSCB\'nin süper güç olarak öne çıkması'], 'Milletler Cemiyeti I. Dünya Savaşı\'ndan sonra, 1920\'de kurulmuştur. Diğerleri II. Dünya Savaşı\'nın doğrudan sonuçlarıdır.'),
  ('Bir öğrenci, aşağıdaki olaylardan hangisinin Atatürk\'ün hayatında askerî bir başarı değil siyasi bir görev olduğunu belirtmelidir?', 'Sofya\'da askerî ataşelik yapması', ['Anafartalar\'da İtilaf çıkarmasını durdurması', 'Muş ve Bitlis\'i geri alması', 'Tobruk\'ta İtalyanlara karşı savaşması'], 'Askerî ataşelik diplomatik temsil niteliği taşıyan bir görevdir; diğerleri cephede kazanılmış askerî başarılardır.'),
  ('İzmir\'in işgalinin Millî Mücadele üzerindeki etkisi aşağıdakilerden hangisidir?', 'Kuvâ-yı Milliye\'nin doğuşunu hızlandırması', ['Lozan\'ın imzalanmasını geciktirmesi', 'Saltanatın hemen kaldırılmasına yol açması', 'Doğu Cephesi\'nin kapanmasını sağlaması'], 'Yunanlıların İzmir\'e çıkması halkta büyük tepki doğurmuş, Batı Anadolu\'da direniş cephelerinin ve Kuvâ-yı Milliye\'nin kurulmasını hızlandırmıştır.'),
  ('Moskova Antlaşması ve Kars Antlaşması ile doğu sınırının belirlenmesi, Millî Mücadele\'nin hangi cephesinde sağlanan güvenceyi gösterir?', 'Doğu Cephesi', ['Batı Cephesi', 'Güney Cephesi', 'Trakya Cephesi'], 'Bu antlaşmalarla Kafkasya sınırı kesinleşmiş ve Doğu Cephesi\'ndeki birliklerin bir kısmı Batı\'ya kaydırılabilmiştir.'),
];
